'use strict';
const photo=(id,w=700)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=80`;
const games=[
 {id:1,name:'Echoes of the Wild',genre:'Adventure',price:2999,old:4999,rating:'4.9',tone:'#41694a',image:photo('photo-1448375240586-882707db888b'),tag:'A WORLD WAITING TO BE FOUND',description:'Step beyond the familiar and into an ancient forest alive with secrets. Explore forgotten ruins, follow the light, and find your own way home.'},
 {id:2,name:'Neon Protocol',genre:'Action',price:2499,old:3999,rating:'4.8',tone:'#67355d',image:photo('photo-1519608487953-e999c86e7455'),tag:'THE CITY NEVER SLEEPS',description:'Navigate a neon-soaked future where every choice leaves a mark. Outsmart the system and take back the city in this fast-paced action adventure.'},
 {id:3,name:'Orbital Drift',genre:'Racing',price:1999,old:null,rating:'4.7',tone:'#995338',image:photo('photo-1464822759023-fed622ff2c3b'),tag:'LEAVE THE LIMITS BEHIND',description:'Race beyond the horizon across impossible mountain circuits. Master every corner and chase the perfect run in a thrilling world of speed.'},
 {id:4,name:'Hollow Bloom',genre:'Indie',price:1499,old:1999,rating:'4.9',tone:'#665779',image:photo('photo-1472396961693-142e6e269027'),tag:'SOMETHING BEAUTIFUL AWAITS',description:'Bring a forgotten woodland back to life in a quiet, handcrafted journey. Meet unusual creatures and discover the magic of small beginnings.'},
 {id:5,name:'Kingdoms of Ash',genre:'RPG',price:3999,old:null,rating:'4.8',tone:'#83633d',image:photo('photo-1518709268805-4e9042af9f23'),tag:'WRITE YOUR OWN LEGEND',description:'A fallen kingdom. An unfinished story. Build your character, gather companions, and decide the fate of a realm balanced between hope and ruin.'},
 {id:6,name:'Little Planet',genre:'Indie',price:1299,old:null,rating:'4.9',tone:'#447c75',image:photo('photo-1441974231531-c6227db76b6e'),tag:'A SMALL WORLD. A BIG HEART.',description:'Grow a tiny world one discovery at a time. Tend your garden, make new friends, and find a little space to call your own.'},
 {id:7,name:'Iron Horizon',genre:'Action',price:3499,old:5999,rating:'4.6',tone:'#52667d',image:photo('photo-1462331940025-496dfbfc7564'),tag:'THE FRONTIER IS CALLING',description:'Pilot a powerful machine across the edge of known space. Face formidable opponents and uncover what lies beyond the last human outpost.'},
 {id:8,name:'Starlight Valley',genre:'Adventure',price:1799,old:null,rating:'4.8',tone:'#67578b',image:photo('photo-1470770841072-f978cf4d019e'),tag:'FOLLOW A DIFFERENT KIND OF STAR',description:'Find your place in a peaceful valley beneath an endless sky. Follow curious trails, meet the locals, and unravel a story written in starlight.'}
];
const $=id=>document.getElementById(id),money=cents=>'$'+(cents/100).toFixed(2);
function restore(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?[...new Set(value)].filter(id=>games.some(g=>g.id===id)):[]}catch{return []}}
let cart=restore('respawn-cart'),wishes=restore('respawn-wishes'),genre='All games',view='all',toastTimer;
function persist(){try{localStorage.setItem('respawn-cart',JSON.stringify(cart));localStorage.setItem('respawn-wishes',JSON.stringify(wishes))}catch{}$('cart-count').textContent=cart.length;$('wish-count').textContent=wishes.length}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2700)}
function filteredGames(){const query=$('search').value.trim().toLowerCase();const list=games.filter(g=>(genre==='All games'||genre===g.genre)&&(view!=='sale'||g.old)&&(view!=='wishlist'||wishes.includes(g.id))&&g.name.toLowerCase().includes(query));if($('sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('sort').value==='high')list.sort((a,b)=>b.price-a.price);if($('sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list}
function render(){const list=filteredGames();$('catalog-title').innerHTML=(view==='wishlist'?'Your saved discoveries':view==='sale'?'Great games. Better prices':'Discover something great')+'<span>.</span>';$('grid').innerHTML=list.length?list.map(g=>`<article class="game-card"><div class="cover" style="--tone:${g.tone}"><img src="${g.image}" alt="${g.name} scenic artwork" loading="lazy"><button class="cover-link" data-detail="${g.id}" aria-label="View ${g.name} details"></button>${g.old?`<span class="discount">−${Math.round((1-g.price/g.old)*100)}%</span>`:''}<button class="wish-button" data-wish="${g.id}" aria-label="${wishes.includes(g.id)?'Remove':'Save'} ${g.name} ${wishes.includes(g.id)?'from':'to'} wishlist" aria-pressed="${wishes.includes(g.id)}">${wishes.includes(g.id)?'♥':'♡'}</button><div class="cover-title"><small>${g.tag}</small>${g.name}</div></div><button class="game-name" data-detail="${g.id}">${g.name}</button><div class="game-meta"><span>${g.genre} · PC</span><span>★ ${g.rating}</span></div><div class="price-row"><strong>${money(g.price)}</strong>${g.old?`<del>${money(g.old)}</del>`:''}<button class="add-button" data-add="${g.id}" aria-label="Add ${g.name} to cart">${cart.includes(g.id)?'✓ Added':'+ Add'}</button></div></article>`).join(''):'<div class="empty"><strong>No games found.</strong><p>Try another search or use “View all games” to explore the collection.</p></div>';document.querySelectorAll('[data-genre]').forEach(b=>{const selected=b.dataset.genre===genre;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected)});persist()}
function add(id){if(cart.includes(id))return toast('This game is already in your cart.');cart.push(id);render();toast('Added to your cart. Your next adventure awaits.')}
function showDetails(id){const g=games.find(g=>g.id===id);$('details').innerHTML=`<img class="detail-image" src="${g.image}" alt="${g.name} scenic artwork"><span class="eyebrow">${g.tag}</span><h2 id="detail-title">${g.name}<span>.</span></h2><div class="detail-tags"><span>${g.genre}</span><span>PC digital edition</span><span>Single-player</span><span>★ ${g.rating} · Sample rating</span></div><p class="detail-copy">${g.description}</p><div class="cart-total"><span>Digital edition</span><strong>${money(g.price)}</strong></div><button class="primary wide" data-add="${g.id}">${cart.includes(g.id)?'Already in your cart':'Add to cart — '+money(g.price)}</button><p class="disclaimer">Fictional game shown for demonstration. Artwork is illustrative.</p>`;$('detail-dialog').showModal()}
function renderCart(){$('cart-items').innerHTML=cart.length?cart.map(id=>{const g=games.find(g=>g.id===id);return `<div class="cart-row"><img src="${g.image}" alt=""><div><strong>${g.name}</strong><p>PC · Digital edition · 1 license</p><button class="remove" data-remove="${g.id}" aria-label="Remove ${g.name} from cart">Remove</button></div><span>${money(g.price)}</span></div>`}).join(''):'<div class="empty"><strong>Your cart is waiting for an adventure.</strong><p>Explore the collection and add a game you love.</p></div>';$('total').textContent=money(cart.reduce((sum,id)=>sum+games.find(g=>g.id===id).price,0));$('checkout').disabled=!cart.length}
function setView(next){view=next;genre='All games';$('search').value='';$('sort').value='featured';render()}
$('filters').innerHTML=['All games','Action','Adventure','RPG','Indie','Racing'].map(g=>`<button class="filter" data-genre="${g}">${g}</button>`).join('');
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();const detail=e.target.closest('[data-detail]');if(detail)showDetails(Number(detail.dataset.detail));const addButton=e.target.closest('[data-add]');if(addButton){add(Number(addButton.dataset.add));if($('detail-dialog').open)addButton.textContent='Already in your cart'}const wish=e.target.closest('[data-wish]');if(wish){const id=Number(wish.dataset.wish);wishes=wishes.includes(id)?wishes.filter(x=>x!==id):[...wishes,id];render()}const filter=e.target.closest('[data-genre]');if(filter){genre=filter.dataset.genre;render()}const link=e.target.closest('[data-view]');if(link)setView(link.dataset.view);const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(id=>id!==Number(remove.dataset.remove));render();renderCart()}});
$('search').addEventListener('input',render);$('sort').addEventListener('change',render);$('open-cart').onclick=()=>{renderCart();$('cart-dialog').showModal()};$('wishlist-view').onclick=()=>{setView('wishlist');$('catalog').scrollIntoView()};$('reset').onclick=()=>setView('all');$('indie-button').onclick=()=>{setView('all');genre='Indie';render();$('catalog').scrollIntoView()};$('feature-button').onclick=$('feature-arrow').onclick=()=>showDetails(1);$('checkout').onclick=()=>{if(!cart.length)return;$('order-items').innerHTML=cart.map(id=>{const g=games.find(g=>g.id===id);return `<div class="order-row"><span>${g.name}</span><strong>${money(g.price)}</strong></div>`}).join('')+`<div class="cart-total"><span>Order total</span><strong>${money(cart.reduce((sum,id)=>sum+games.find(g=>g.id===id).price,0))}</strong></div>`;$('cart-dialog').close();$('order-dialog').showModal()};document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const bounds=dialog.getBoundingClientRect();if(e.clientX<bounds.left||e.clientX>bounds.right||e.clientY<bounds.top||e.clientY>bounds.bottom)dialog.close()}}));render();
